CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(60) NOT NULL,password_hash VARCHAR(100) NOT NULL,role ENUM('owner','admin','kasir') NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sessions(token_hash CHAR(64) PRIMARY KEY,user_id INT NOT NULL,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY(expires_at),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(40) NOT NULL UNIQUE,sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS menu_items(id INT AUTO_INCREMENT PRIMARY KEY,category_id INT NOT NULL,name VARCHAR(80) NOT NULL,description VARCHAR(200) DEFAULT '',price INT NOT NULL,available TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS dining_tables(id INT AUTO_INCREMENT PRIMARY KEY,number INT NOT NULL UNIQUE,code CHAR(12) NOT NULL UNIQUE,active TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS orders(id INT AUTO_INCREMENT PRIMARY KEY,code VARCHAR(12) NOT NULL UNIQUE,table_id INT NULL,table_number INT NOT NULL,customer_name VARCHAR(40) NOT NULL DEFAULT 'Pelanggan',status ENUM('menunggu','diterima','diproses','selesai','dibatalkan') NOT NULL DEFAULT 'menunggu',payment_method ENUM('qris','tunai') NOT NULL,payment_status ENUM('belum','lunas') NOT NULL DEFAULT 'belum',total INT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,paid_at DATETIME NULL,KEY(created_at),KEY(status),FOREIGN KEY(table_id) REFERENCES dining_tables(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,menu_item_id INT NULL,name VARCHAR(80) NOT NULL,price INT NOT NULL,qty INT NOT NULL,note VARCHAR(120) DEFAULT '',KEY(order_id),KEY(menu_item_id),FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
